#[derive(Clone)]
struct Rows {
    attributes: DatasetAttributes,
    attributes_version: u64,
    records: Vec<Vec<u8>>,
    identities: Vec<Vec<u8>>,
    version: u64,
    catalog: CatalogListEntry,
}

#[derive(Clone)]
pub(super) struct CardState {
    base: Rows,
    index: Rows,
}

fn drift(detail: impl Into<String>) -> CorpusProblem {
    CorpusProblem::new("carddemo.online.card_base_index_drift", detail)
}

fn read_rows(server: &ProductServer, name: &str) -> Result<Rows, CorpusProblem> {
    let dataset =
        DatasetName::new(name, 128).map_err(|_| drift("selected card dataset name is invalid"))?;
    let (attributes, attributes_version) = match server
        .dataset_service()
        .invoke(DatasetRequest::Attributes {
            dataset: dataset.clone(),
        })
        .map_err(terminal_problem)?
    {
        DatasetResult::Attributes {
            attributes,
            version,
        } => (attributes, version),
        _ => return Err(drift("selected card attributes returned the wrong result")),
    };
    let (records, identities, version) = match server
        .dataset_service()
        .invoke(DatasetRequest::Read {
            dataset,
            member: None,
            key: None,
            max_records: 51,
            control: Default::default(),
        })
        .map_err(terminal_problem)?
    {
        DatasetResult::Records {
            records,
            identities,
            version,
        } => (records, identities, version),
        _ => return Err(drift("selected card read returned the wrong result")),
    };
    let catalog = match server
        .dataset_service()
        .invoke(DatasetRequest::ListCatalog {
            pattern: name.into(),
            start: None,
            max_items: 2,
        })
        .map_err(terminal_problem)?
    {
        DatasetResult::CatalogEntries {
            mut entries,
            more: false,
        } if entries.len() == 1 => entries.remove(0),
        _ => return Err(drift("selected card catalog was not one complete entry")),
    };
    Ok(Rows {
        attributes,
        attributes_version,
        records,
        identities,
        version,
        catalog,
    })
}

pub(super) fn capture(server: &ProductServer) -> Result<CardState, CorpusProblem> {
    Ok(CardState {
        base: read_rows(server, BASE)?,
        index: read_rows(server, INDEX)?,
    })
}

fn expected_record(position: usize, rewritten: bool) -> &'static [u8] {
    if rewritten && position == 0 {
        REWRITTEN_RECORD
    } else {
        SEED_RECORDS[position]
    }
}

fn layout_matches(rows: &Rows, name: &str, offset: u32, length: u32) -> bool {
    rows.attributes.organization == DatasetOrganization::KeySequenced
        && rows.attributes.record_format == RecordFormat::Fixed
        && rows.attributes.logical_record_length == 150
        && rows.attributes.key_offset == Some(offset)
        && rows.attributes.key_length == Some(length)
        && rows.attributes.ccsid == Some(37)
        && rows.version != 0
        && rows.attributes_version == rows.version
        && rows.catalog.version == rows.version
        && rows.catalog.name.as_str() == name
}

fn state_matches(state: &CardState, rewritten: bool) -> bool {
    layout_matches(&state.base, BASE, 0, 16)
        && state.base.catalog.kind == CatalogEntryKind::Dataset
        && state.base.catalog.related.is_none()
        && layout_matches(&state.index, INDEX, 16, 11)
        // Declared admitted fixture representation; no separate IBM PATH parity.
        && state.index.catalog.kind == CatalogEntryKind::AlternateIndex
        && state.index.catalog.related.as_ref().map(DatasetName::as_str) == Some(BASE)
        && state.base.records.iter().map(Vec::as_slice)
            .eq((0..50).map(|position| expected_record(position, rewritten)))
        && state.base.identities.iter().map(Vec::as_slice).eq(PRIMARY_KEYS)
        && state.index.records.iter().map(Vec::as_slice)
            .eq(AIX_ORDER.into_iter().map(|position| expected_record(position, rewritten)))
        && state.index.identities.iter().map(Vec::as_slice)
            .eq(AIX_ORDER.into_iter().map(|position| PRIMARY_KEYS[position]))
}

pub(super) fn require_seed(state: &CardState) -> Result<(), CorpusProblem> {
    if !state_matches(state, false) {
        return Err(drift(
            "complete raw base/index seed, identity, layout or relationship differs",
        ));
    }
    Ok(())
}

pub(super) fn compare_rewrite(
    observations: &mut RouteObservations,
    before: &CardState,
    after: &CardState,
) -> Result<(), CorpusProblem> {
    observations.compare(
        AuthorityKind::Journey,
        "CD.J05",
        "atomic base/index state",
        !state_matches(before, false)
            || !state_matches(after, true)
            || before.base.version.checked_add(1) != Some(after.base.version)
            || before.index.version.checked_add(1) != Some(after.index.version),
        || Ok(drift(format!(
            "complete before/after base/index agreement failed; base versions={}/{}; index versions={}/{}",
            before.base.version, after.base.version, before.index.version, after.index.version,
        ))),
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    fn state(rewritten: bool, base_version: u64, index_version: u64) -> CardState {
        let rows = |name: &str, offset, length, kind, related, version, positions: &[usize]| Rows {
            attributes: DatasetAttributes {
                organization: DatasetOrganization::KeySequenced,
                record_format: RecordFormat::Fixed,
                logical_record_length: 150,
                key_offset: Some(offset),
                key_length: Some(length),
                ccsid: Some(37),
            },
            attributes_version: version,
            records: positions
                .iter()
                .map(|position| expected_record(*position, rewritten).to_vec())
                .collect(),
            identities: positions
                .iter()
                .map(|position| PRIMARY_KEYS[*position].to_vec())
                .collect(),
            version,
            catalog: CatalogListEntry {
                name: DatasetName::new(name, 128).unwrap(),
                kind,
                related,
                version,
            },
        };
        CardState {
            base: rows(
                BASE,
                0,
                16,
                CatalogEntryKind::Dataset,
                None,
                base_version,
                &(0..50).collect::<Vec<_>>(),
            ),
            index: rows(
                INDEX,
                16,
                11,
                CatalogEntryKind::AlternateIndex,
                Some(DatasetName::new(BASE, 128).unwrap()),
                index_version,
                &AIX_ORDER,
            ),
        }
    }

    fn refused(before: &CardState, after: &CardState) {
        let mut observations = RouteObservations::default();
        let error = compare_rewrite(&mut observations, before, after).unwrap_err();
        assert_eq!(error.code, "carddemo.online.card_base_index_drift");
        assert!(observations.journeys().is_empty());
        assert!(observations.issues().is_empty());
    }

    #[test]
    fn exact_complete_rewrite_requires_both_published_versions() {
        let before = state(false, 4, 7);
        let after = state(true, 5, 8);
        require_seed(&before).unwrap();
        let mut observations = RouteObservations::default();
        compare_rewrite(&mut observations, &before, &after).unwrap();
        assert_eq!(
            observations.journeys(),
            &[("CD.J05".into(), vec!["atomic base/index state".into()])]
        );
        assert!(observations.issues().is_empty());
    }

    #[test]
    fn corrupted_base_payload_and_primary_identity_refuse() {
        let before = state(false, 4, 7);
        let mut after = state(true, 5, 8);
        after.base.records[20][80] ^= 1;
        refused(&before, &after);
        let mut after = state(true, 5, 8);
        after.base.identities[20][0] ^= 1;
        refused(&before, &after);
    }

    #[test]
    fn missing_extra_and_reordered_rows_refuse() {
        let before = state(false, 4, 7);
        let mut after = state(true, 5, 8);
        after.base.records.pop();
        after.base.identities.pop();
        refused(&before, &after);
        let mut after = state(true, 5, 8);
        after.base.records.push(after.base.records[0].clone());
        after.base.identities.push(after.base.identities[0].clone());
        refused(&before, &after);
        let mut after = state(true, 5, 8);
        after.index.records.swap(0, 1);
        after.index.identities.swap(0, 1);
        refused(&before, &after);
    }

    #[test]
    fn corrupted_alternate_record_and_mapping_refuse() {
        let before = state(false, 4, 7);
        let mut after = state(true, 5, 8);
        after.index.records[10][16] ^= 1;
        refused(&before, &after);
        let mut after = state(true, 5, 8);
        after.index.identities.swap(10, 11);
        refused(&before, &after);
        let mut after = state(true, 5, 8);
        after.index.records.pop();
        after.index.identities.pop();
        refused(&before, &after);
    }

    #[test]
    fn layout_catalog_kind_and_relationship_refuse() {
        let before = state(false, 4, 7);
        let mut after = state(true, 5, 8);
        after.index.attributes.key_offset = Some(0);
        refused(&before, &after);
        let mut after = state(true, 5, 8);
        after.index.catalog.related = Some(DatasetName::new("WRONG.BASE", 128).unwrap());
        refused(&before, &after);
        let mut after = state(true, 5, 8);
        after.index.catalog.kind = CatalogEntryKind::Path;
        refused(&before, &after);
    }

    #[test]
    fn unchanged_or_inconsistent_base_and_index_versions_refuse() {
        let before = state(false, 4, 7);
        for (base, index) in [(4, 8), (5, 7), (6, 8), (5, 9)] {
            refused(&before, &state(true, base, index));
        }
        let mut after = state(true, 5, 8);
        after.index.attributes_version = 7;
        refused(&before, &after);
        let mut after = state(true, 5, 8);
        after.index.catalog.version = 7;
        refused(&before, &after);
    }

    #[test]
    fn corrupt_baseline_refuses_before_new_evidence() {
        let mut before = state(false, 4, 7);
        before.base.records[0][30] ^= 1;
        assert!(require_seed(&before).is_err());
        refused(&before, &state(true, 5, 8));
    }
}
